sites.find:
for (face_index = 0; face_index < 2; ++face_index) {
    if (face_index == 0) {
        cRFaceQuad* face =
            &facequads[2 * column
                + 2 * row * path->width_cells + face_index];
        face->header_word = 0;
        face->vertex_0 = column + row * ((unsigned short)path->width_cells + 1);
        face->vertex_1 = row * ((unsigned short)path->width_cells + 1) + column + 1;
        face->vertex_2 =
            (row + 1) * ((unsigned short)path->width_cells + 1) + column + 1;
        face->vertex_3 =
            column + (row + 1) * ((unsigned short)path->width_cells + 1);
        face->texture_ref =
            g_texture_refs.Add(texture_a, 0, 0);
        face->uv[0].u = u0;
        face->uv[0].v = v0;
        face->uv[1].u = u1;
        face->uv[1].v = v0;
        face->uv[2].u = u1;
        face->uv[2].v = v1;
        face->uv[3].u = u0;
        face->uv[3].v = v1;
    } else {
        cRFaceQuad* face =
            &facequads[2 * column
                + 2 * row * path->width_cells + face_index];
        face->header_word = 0;
        face->vertex_0 = row * ((unsigned short)path->width_cells + 1) + column + 1;
        face->vertex_1 = column + row * ((unsigned short)path->width_cells + 1);
        face->vertex_2 =
            column + (row + 1) * ((unsigned short)path->width_cells + 1);
        face->vertex_3 =
            (row + 1) * ((unsigned short)path->width_cells + 1) + column + 1;
        face->texture_ref =
            g_texture_refs.Add(texture_b, 0, 0);
        face->uv[0].u = u1;
        face->uv[0].v = v0;
        face->uv[1].u = u0;
        face->uv[1].v = v0;
        face->uv[2].u = u0;
        face->uv[2].v = v1;
        face->uv[3].u = u1;
        face->uv[3].v = v1;
    }
}

